def landing(lang, c, prefix, play, blocks):
    t=COPY[lang]; ix=c['index']; e=escape
    cta=(f'<a class="play" href="{play}">{e(ix["play"])}</a>' if PLAY_AVAILABLE else f'<span class="play upcoming">{e(t["coming"])}</span>')
    features=''.join(f'<li><img src="{prefix}assets/{asset}" alt="" width="64" height="64" loading="lazy"><div><h3>{e(title)}</h3><p>{e(body)}</p></div></li>' for (title,body),asset in zip(t['features'],['drawing.png','voice.png','yearbook.png']))
    docs=''.join(f'<a href="{page}.html">{e(c["nav"][page])}</a>' for page in ['privacy','terms','delete'])
    return f'''<section class="welcome" aria-labelledby="welcome-title">
<div class="welcome-copy"><h1 id="welcome-title">{' '.join(f'<span>{e(line)}</span>' for line in t['hero'])}</h1>
<p class="welcome-intro">{e(t['intro']).replace(chr(10),'<br>')}</p>
<div class="download">{cta}<p>{e(t['note'])}</p></div>
<a class="receive-jump" href="#receive">{e(t['receive'])} <span aria-hidden="true">↗</span></a></div>
<div class="welcome-art"><img src="{prefix}assets/symbol.png" alt="" width="600" height="600" fetchpriority="high"></div></section>
<section class="story" aria-labelledby="story-title"><h2 id="story-title">{e(t['section'])}</h2><ul class="features">{features}</ul></section>
<details class="receive" id="receive"><summary><img src="{prefix}assets/yearbook.png" alt="" width="44" height="44"><span>{e(t['received'])}</span><i class="chevron" aria-hidden="true"></i></summary><div class="receive-body"><p>{e(t['receiveNote'])}</p>{blocks([('ol',ix['receive'])])}</div></details>
<nav class="document-links" aria-label="{e(ix['docsTitle'])}">{docs}</nav>'''

